syntax:
from pydantic import BaseModel, Field, ValidationError

class Ticket(BaseModel):
    title: str
    priority: int = Field(ge=1, le=5)
    owner: str | None = None

payload = {'title': 'CPU high', 'priority': '3'}
model = Ticket.model_validate(payload)
print(model.model_dump())

try:
    Ticket.model_validate({'title': '', 'priority': 9})
except ValidationError as exc:
    print(exc.errors())

