from pydantic import BaseModel, Field

class DeployRequest(BaseModel):
    service: str
    environment: str
    replicas: int = Field(ge=1, le=20)
    dry_run: bool = False

request = DeployRequest.model_validate({
    'service': 'billing-api',
    'environment': 'staging',
    'replicas': '3',
})

print(request.model_dump())
# {'service': 'billing-api', 'environment': 'staging', 'replicas': 3, 'dry_run': False}
